Lemma cc_split3 : forall len o n, 0 <= o <= n -> n <= len -> o mod 8 = 0 -> n mod 8 = 0 -> len mod 8 = 0 ->
  cc_shadow len o = poison_bytes (Z.to_nat (o / 8)) 0 ++ (poison_bytes (Z.to_nat ((n - o) / 8)) 0xfc ++ poison_bytes (Z.to_nat ((len - n) / 8)) 0xfc)
  /\ cc_shadow len n = poison_bytes (Z.to_nat (o / 8)) 0 ++ (poison_bytes (Z.to_nat ((n - o) / 8)) 0 ++ poison_bytes (Z.to_nat ((len - n) / 8)) 0xfc).
Proof.
